import * as React from "react";
import { cn, type Tilt } from "@/lib/pixel3d";
import { Card, CardTitle } from "@/components/ui/card";
import { Badge, type BadgeProps } from "@/components/ui/badge";
import { PixelAvatar } from "@/components/ui/pixel-avatar";

/**
 * TeamCard — a hackathon team on one card sticker: the crew's pixel avatars, the team name,
 * its track badge and one action. No meta rows, no stats strip (Few Voices).
 *
 *   <TeamCard name="Null Pointers" track="AI tools" members={["Ada", "Linus", "Grace"]}
 *     action={<Button size="sm">Join team</Button>} />
 */
export interface TeamCardProps extends Omit<React.HTMLAttributes<HTMLDivElement>, "children"> {
  name: string;
  /** Member names; each becomes a PixelAvatar. */
  members: string[];
  track?: React.ReactNode;
  trackTone?: BadgeProps["tone"];
  /** The one action (a Button). */
  action?: React.ReactNode;
  /** Avatars shown before the rest collapse into "+N". */
  maxAvatars?: number;
  tilt?: Tilt;
}

export const TeamCard = React.forwardRef<HTMLDivElement, TeamCardProps>(
  ({ name, members, track, trackTone = "sky", action, maxAvatars = 4, tilt = "auto", className, ...props }, ref) => {
    const shown = members.slice(0, maxAvatars);
    const rest = members.length - shown.length;
    return (
      <Card ref={ref} data-slot="team-card" tilt={tilt} className={cn("w-full max-w-sm gap-6", className)} {...props}>
        <ul aria-label={`${name} members`} className="flex flex-wrap items-center gap-3">
          {shown.map((m) => (
            <li key={m} className="flex">
              <PixelAvatar name={m} size="md" />
            </li>
          ))}
          {rest > 0 && (
            <li
              className="sticker face-lid crooked flex size-14 items-center justify-center text-lg font-extrabold tabular-nums"
              style={{ ["--p3d-tilt" as string]: "1.5deg" }}
            >
              <span aria-hidden>+{rest}</span>
              <span className="sr-only">and {rest} more</span>
            </li>
          )}
        </ul>
        <div className="flex flex-col items-start gap-3">
          <CardTitle>{name}</CardTitle>
          {track && <Badge tone={trackTone}>{track}</Badge>}
        </div>
        {action && <div className="flex">{action}</div>}
      </Card>
    );
  }
);
TeamCard.displayName = "TeamCard";

"use client";
import * as React from "react";
import { cn, useTilt, type Tilt } from "@/lib/pixel3d";

/**
 * Card — a big sticker with stepped 3-step corners. `interactive` adds the 3D corner-peel.
 * Never nest cards (DESIGN.md). Keep to: media, one heading, one line, one action.
 */
export interface CardProps extends React.HTMLAttributes<HTMLDivElement> {
  tilt?: Tilt;
  interactive?: boolean;
  face?: "paper" | "pink" | "lime" | "sky" | "butter" | "ink";
}

const faces = {
  paper: "face-paper",
  pink: "face-pink",
  lime: "face-lime",
  sky: "face-sky",
  butter: "face-butter",
  ink: "face-ink",
} as const;

export const Card = React.forwardRef<HTMLDivElement, CardProps>(
  ({ className, tilt = false, interactive = false, face = "paper", style, ...props }, ref) => {
    const tiltStyle = useTilt(tilt, 1.5);
    return (
      <div
        ref={ref}
        data-slot="card"
        style={{ ...tiltStyle, ...style }}
        className={cn(
          "sticker sticker-lg flex flex-col gap-5 p-7",
          faces[face],
          interactive ? "peel-3d cursor-pointer" : "crooked",
          className
        )}
        {...props}
      />
    );
  }
);
Card.displayName = "Card";

export const CardHeader = ({ className, ...p }: React.HTMLAttributes<HTMLDivElement>) => (
  <div data-slot="card-header" className={cn("flex flex-col gap-2", className)} {...p} />
);
export const CardTitle = ({ className, ...p }: React.HTMLAttributes<HTMLHeadingElement>) => (
  <h3 data-slot="card-title" className={cn("text-2xl font-extrabold leading-tight tracking-[-0.02em]", className)} {...p} />
);
export const CardDescription = ({ className, ...p }: React.HTMLAttributes<HTMLParagraphElement>) => (
  <p data-slot="card-description" className={cn("text-base leading-relaxed opacity-80", className)} {...p} />
);
export const CardContent = ({ className, ...p }: React.HTMLAttributes<HTMLDivElement>) => (
  <div data-slot="card-content" className={cn("flex flex-col gap-4", className)} {...p} />
);
export const CardFooter = ({ className, ...p }: React.HTMLAttributes<HTMLDivElement>) => (
  <div data-slot="card-footer" className={cn("flex items-center justify-between gap-4", className)} {...p} />
);
/** Full-bleed media area (image, three.js <Sticker3D/>, chart). */
export const CardMedia = ({ className, ...p }: React.HTMLAttributes<HTMLDivElement>) => (
  <div data-slot="card-media" className={cn("-mx-3 -mt-3 overflow-hidden bg-lid-deep/40", className)} {...p} />
);

import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "@/lib/pixel3d";

/** Badge — a tiny sticker. Use sparingly: never "a badge on every item". */
export const badgeVariants = cva(
  "sticker crooked inline-flex h-8 items-center gap-1.5 px-3 text-sm font-extrabold leading-none [&_svg]:pixel-icon [&_svg]:size-4",
  {
    variants: {
      tone: {
        paper: "face-paper",
        pink: "face-pink",
        lime: "face-lime",
        sky: "face-sky",
        tomato: "face-tomato",
        butter: "face-butter",
        ink: "face-ink",
      },
    },
    defaultVariants: { tone: "paper" },
  }
);

export interface BadgeProps extends React.HTMLAttributes<HTMLSpanElement>, VariantProps<typeof badgeVariants> {
  tilt?: number;
}

export function Badge({ className, tone, tilt = -2, style, ...props }: BadgeProps) {
  return (
    <span
      data-slot="badge"
      className={cn(badgeVariants({ tone }), className)}
      style={{ ["--p3d-tilt" as string]: `${tilt}deg`, ...style }}
      {...props}
    />
  );
}

"use client";
import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn, useTilt, type Tilt } from "@/lib/pixel3d";
import { Sticker3D } from "@/components/ui/three/sticker-3d";
import { defaultPalette } from "@/components/ui/three/patterns";

/**
 * PixelAvatar — a deterministic, symmetric 8×8 pixel sprite (identicon-style) generated from a
 * name in the vinyl inks, printed on a crooked paper sticker. Same name, same sprite, always.
 * `three` renders the sprite as a real voxel sticker on the shared canvas instead.
 *
 *   <PixelAvatar name="Ada" />
 *   <PixelAvatar name="Ada" size="lg" three />
 */
export const pixelAvatarVariants = cva("sticker face-paper crooked inline-flex shrink-0 items-center justify-center", {
  variants: {
    size: {
      sm: "size-10 p-1",
      md: "size-14 p-1.5",
      lg: "size-20 p-2",
    },
  },
  defaultVariants: { size: "md" },
});

const threeSizes = { sm: "size-12", md: "size-20", lg: "size-32" } as const;

export interface PixelAvatarProps
  extends Omit<React.HTMLAttributes<HTMLSpanElement>, "children">,
    VariantProps<typeof pixelAvatarVariants> {
  name: string;
  /** Resting angle. "auto" (default) picks a stable crooked angle; false = straight. */
  tilt?: Tilt;
  /** Render as a three.js voxel sticker (needs <StickerCanvas>). */
  three?: boolean;
}

const INK_KEYS = ["p", "s", "l", "b", "t"] as const;

function hash(s: string) {
  let h = 2166136261;
  for (let i = 0; i < s.length; i++) h = Math.imul(h ^ s.charCodeAt(i), 16777619);
  return h >>> 0;
}
function mulberry32(seed: number) {
  let a = seed;
  return () => {
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/** The 8×8 sprite for a name, as pattern rows (keys map to the default ink palette). */
export function pixelAvatarPattern(name: string): string[] {
  const seed = hash(name.trim().toLowerCase() || "?");
  const rnd = mulberry32(seed);
  const mi = seed % INK_KEYS.length;
  const main = INK_KEYS[mi];
  const accentKey = INK_KEYS[(mi + 1 + ((seed >>> 8) % (INK_KEYS.length - 1))) % INK_KEYS.length];
  for (let attempt = 0; attempt < 8; attempt++) {
    const rows: string[] = [];
    let filled = 0;
    for (let y = 0; y < 8; y++) {
      let half = "";
      for (let x = 0; x < 4; x++) {
        const r = rnd();
        // denser towards the middle columns so sprites read as a body, not noise
        const p = x === 0 ? 0.38 : 0.58;
        const k = r < p ? main : r < p + 0.12 ? accentKey : r < p + 0.17 ? "k" : ".";
        if (k !== ".") filled++;
        half += k;
      }
      rows.push(half + [...half].reverse().join(""));
    }
    if (filled >= 12 && filled <= 26) return rows;
  }
  return ["..pppp..", ".pppppp.", "pp.pp.pp", "pppppppp", "pppppppp", ".pp..pp.", "pp....pp", "p......p"].map((r) =>
    r.replace(/p/g, main)
  );
}

export const PixelAvatar = React.forwardRef<HTMLSpanElement, PixelAvatarProps>(
  ({ name, size, tilt = "auto", three = false, className, style, ...props }, ref) => {
    const tiltStyle = useTilt(tilt);
    const pattern = React.useMemo(() => pixelAvatarPattern(name), [name]);
    if (three) {
      return (
        <span ref={ref} data-slot="pixel-avatar" className={cn("inline-flex shrink-0", className)} style={style} {...props}>
          <Sticker3D pattern={pattern} label={name} className={threeSizes[size ?? "md"]} />
        </span>
      );
    }
    return (
      <span
        ref={ref}
        role="img"
        aria-label={name}
        data-slot="pixel-avatar"
        className={cn(pixelAvatarVariants({ size }), className)}
        style={{ ...tiltStyle, ...style }}
        {...props}
      >
        <svg viewBox="0 0 8 8" className="pixel-icon size-full" aria-hidden>
          {pattern.map((row, y) =>
            [...row].map((k, x) =>
              k === "." ? null : <rect key={`${x}-${y}`} x={x} y={y} width={1} height={1} fill={defaultPalette[k]} />
            )
          )}
        </svg>
      </span>
    );
  }
);
PixelAvatar.displayName = "PixelAvatar";
